Definition lregs (R : bvmap 5 word) (sp ov : Z) : Prop :=
  getr R (reg 2) = Z_to_bv 64 (sp - 64) /\ getr R (reg 8) = Z_to_bv 64 ov /\ getr R (reg 9) = Z_to_bv 64 (ov + 32) /\ getr R (reg 18) = Z_to_bv 64 SBL
  /\ getr R (reg 19) = Z_to_bv 64 ((ov + 32) / 8 + SBL).
